"use strict";

// C10: the throwing callable is a BLOCK-SCOPED SHADOW of a perfectly safe
// outer binding of the same name.
//
//     function bail() { return "safe"; }      // outer -- safe
//     { const bail = () => { throw ... }; bail(); }   // inner -- throws
//
// RWF-016 refused any shadowed name outright, which was sound but blind:
// it could not prove this cutoff. RWF-028 resolves the shadow properly
// instead, nearest binding first -- which is also what makes the MIRRORED
// case safe, where the inner binding is the harmless one. `valid.js`
// carries that mirrored control, and it is the single most important
// false-AFFECTED control in this task: resolving a call to an outer
// throwing binding across a safe shadow would be a verdict invented out of
// a name collision.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

// The OUTER `bail` is safe. Nothing about this function ends anything.
function bail() {
  return "outer-is-safe";
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  {
    const bail = () => {
      throw new Error("boom");
    };
    bail();
  }
}

module.exports = safeOp;
